const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',dumbbell:'<path d="m6 6 12 12M4 9l5-5m6 16 5-5M2 7l5-5m10 20 5-5"/>',chart:'<path d="M4 4v16h17M8 15l4-5 4 3 5-7"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',fire:'<path d="M13 2c2 6-2 7-2 10-2-1-3-2-3-5-4 4-5 8-2 12 4 5 13 2 13-4 0-4-3-7-6-13Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L19 6"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5L12 2Z"/>',play:'<path d="m8 5 11 7-11 7Z"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>'};
const icon=(name,size=19)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
const escapeHTML=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages=[['today','今日概览','grid'],['training','记录','chart'],['plan','训练计划','calendar']];
function readLocal(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let records=readLocal('nextstep.records',[]);if(!Array.isArray(records))records=[];
const profileDefaults={name:'',weight:'',height:'',goal:'',frequency:'',lifestyle:'',experience:'',duration:'',equipment:''};
let profile={...profileDefaults,...readLocal('nextstep.profile',{})};
const lastActive=Number(readLocal('nextstep.lastActive',0));
let reminderReason=!profile.updatedAt?'first':lastActive&&Date.now()-lastActive>=30*86400000?'return':'';
let reminderDismissed=false;
let draft=readLocal('nextstep.draft',null),selectedExercise=Number(draft?.activeExercise)||0,restEnd=Number(draft?.restEnd)||0,period='week',planDay=2;
let currentPage='today';let toastTimer;
if(draft&&Number.isFinite(draft.startedAt)&&draft.startedAt>0&&records.some(r=>r.workoutId===String(draft.startedAt)||r.startedAt===draft.startedAt)){draft=null;restEnd=0;selectedExercise=0;try{localStorage.removeItem('nextstep.draft')}catch{}}

function validActivityDate(date){return typeof date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(date)&&localDate(new Date(date+'T12:00:00'))===date&&date<=localDate()}
function validStepRecord(r){return r&&r.kind==='steps'&&r.provider==='health-connect'&&validActivityDate(r.date)&&Number.isSafeInteger(r.steps)&&r.steps>=0&&Number.isFinite(r.syncedAt)&&r.syncedAt>0&&Array.isArray(r.sources)&&r.sources.every(s=>typeof s==='string')}
let activityRecords=readLocal('nextstep.activityRecords',[]);activityRecords=Array.isArray(activityRecords)?activityRecords.filter(validStepRecord):[];
let pendingActivityRecords=null;
let healthSteps={status:'idle'},healthPending=false,healthTimer;
function exportData(){return {version:2,profile,records,activityRecords}}
function saveStepRecords(value){
const byDate=new Map((pendingActivityRecords||activityRecords).map(r=>[r.date,r]));
for(const day of value.days){if(day.steps===null)continue;const old=byDate.get(day.date);if(old&&old.syncedAt>value.syncedAt)continue;byDate.set(day.date,{kind:'steps',provider:'health-connect',date:day.date,steps:day.steps,sources:[...(day.sources||value.sources)],syncedAt:value.syncedAt})}
const next=[...byDate.values()].sort((a,b)=>b.date.localeCompare(a.date));
if(!saveLocal('nextstep.activityRecords',next)){pendingActivityRecords=next;return false}
activityRecords=next;pendingActivityRecords=null;return true;
}
function retryStepSave(){if(!pendingActivityRecords)return;const next=pendingActivityRecords;if(!saveLocal('nextstep.activityRecords',next))return;activityRecords=next;pendingActivityRecords=null;updateHealthCard();toast('每日步数记录已保存')}
function savedStepDays(){return Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));const date=localDate(d),record=activityRecords.find(r=>r.date===date);return {date,steps:record?.steps??null}})}
function stepHistory(){const sorted=[...activityRecords].sort((a,b)=>b.date.localeCompare(a.date));return `<section id="step-history" class="card health-history"><div class="card-head"><h2>每日步数记录</h2><button class="text-button" data-action="export">导出全部记录</button></div><p class="subtitle">${sorted.length?'已保存 '+sorted.length+' 天 · 累计 '+sorted.reduce((n,r)=>n+r.steps,0).toLocaleString()+' 步':'尚未保存步数。连接 Health Connect 后自动记录。'}${pendingActivityRecords?' · 最新读取尚未保存，请返回今日概览重试。':''}</p><p class="small-label">每日累计值按日期更新，不算作一次训练；撤销授权后已保存的记录仍保留。</p>${sorted.length?`<details class="step-history-list"><summary>查看每日记录（${sorted.length} 天）</summary>${sorted.map(r=>`<article class="step-history-row"><div><strong>${escapeHTML(r.date)}</strong><p class="health-meta">来源：${escapeHTML(r.sources.join('、')||'Health Connect')}<br>同步于 ${escapeHTML(new Date(r.syncedAt).toLocaleString())}</p></div><strong>${r.steps.toLocaleString()} 步</strong></article>`).join('')}</details>`:''}</section>`}
function healthNative(){return window.NextStepAndroid&&typeof window.NextStepAndroid.readHealthSteps==='function'}
function healthCard(){
const native=healthNative(),ready=healthSteps.status==='ready',savedDays=savedStepDays(),hasSaved=savedDays.some(d=>d.steps!==null),days=ready?healthSteps.days.map(d=>({...d,steps:d.steps??activityRecords.find(r=>r.date===d.date)?.steps??null})):savedDays,todaySteps=days.find(d=>d.date===localDate())?.steps;
const latest=days.filter(d=>d.steps!==null).map(d=>d.date).sort().pop();
const message=!native?'请使用 Android 安装包连接手机健康数据。':healthPending?'正在读取步数…':ready?(healthSteps.days.some(d=>d.steps!==null)?(todaySteps===undefined||todaySteps===null?'今日暂无共享步数'+(latest?' · 最新数据 '+latest.slice(5):''):'今日累计 · 与训练分别统计'):'暂无共享步数。请在 Health Connect 检查步数数据和来源应用的共享设置。'):healthSteps.message||'授权读取最近七天步数，查看每日活动。';
return `<section id="health-card" class="health-card" aria-labelledby="health-title"><div class="health-heading"><h2 id="health-title">每日活动</h2><span class="small-label">Health Connect</span></div><div class="health-number">${todaySteps!==undefined&&todaySteps!==null?todaySteps.toLocaleString():'—'}<small>今日步数</small></div><p class="subtitle" role="status">${escapeHTML(message)}${pendingActivityRecords?' 最新步数尚未保存，请重试保存。':''}</p><div class="health-actions health-primary-actions">${native?`<button class="text-button" data-action="health-read" ${healthPending?'disabled':''}>${healthSteps.status==='permission'||healthSteps.status==='idle'?'连接步数':'刷新步数'}</button>`:''}<button class="text-button" data-page="training">活动记录</button>${pendingActivityRecords?'<button class="primary-button" data-action="health-save">重试保存步数</button>':''}</div><details class="health-details"><summary>七天步数与同步说明</summary>${ready||hasSaved?`<div class="health-days" aria-label="最近七天每日步数">${days.map(d=>`<div class="health-day"><span>${escapeHTML(d.date.slice(5))}</span><strong>${d.steps===null?'—':d.steps.toLocaleString()}</strong></div>`).join('')}</div><p class="health-meta">本次读取 ${escapeHTML(new Date(ready?healthSteps.syncedAt:Math.max(...activityRecords.map(r=>r.syncedAt))).toLocaleString())}<br>数据来源：${escapeHTML((ready?healthSteps.sources:[...new Set(activityRecords.flatMap(r=>r.sources))]).join('、')||'暂无来源')}<br>— 表示暂无数据，不代表走了 0 步。保存过的日期在暂无新数据时保留原值。</p>`:''}<p class="health-meta">读取范围包含今天，截至刷新时刻。若近期缺失，请先在来源健康应用同步，再在 Health Connect 的步数数据中核对对应日期。历史读取权限限制不要求今天的数据等待数天；NextStep 无法读取来源尚未共享的步数。</p>${native?'<div class="health-actions"><button class="text-button" data-action="health-settings">打开 Health Connect</button><button class="text-button" data-action="health-privacy">数据说明</button></div>':''}</details></section>`}
function updateHealthCard(){
const card=document.getElementById('health-card'),active=document.activeElement,action=active?.dataset?.action;
const focused=card?.contains?.(active);
if(card&&currentPage==='today'){const expanded=card.querySelector?.('.health-details')?.open;card.outerHTML=healthCard();if(expanded)document.getElementById('health-card').querySelector('.health-details').open=true;if(focused&&['health-read','health-save','health-settings','health-privacy'].includes(action)){const next=document.getElementById('health-card');(next.querySelector('[data-action="'+action+'"]')||next.querySelector('[data-action="health-read"]'))?.focus({preventScroll:true})}}
const history=document.getElementById('step-history');if(history&&currentPage==='training'){const expanded=history.querySelector?.('details')?.open,focusedExport=history.contains?.(active)&&action==='export';history.outerHTML=stepHistory();const next=document.getElementById('step-history');if(expanded&&next.querySelector?.('details'))next.querySelector('details').open=true;if(focusedExport)next.querySelector('[data-action="export"]')?.focus({preventScroll:true})}
}
function refreshHealthSteps(authorize=false){if(!healthNative()||healthPending)return;healthPending=true;updateHealthCard();clearTimeout(healthTimer);healthTimer=setTimeout(()=>{healthPending=false;healthSteps={status:'error',message:'读取超时，请重试'};updateHealthCard()},25000);try{window.NextStepAndroid.readHealthSteps(!!authorize)}catch{window.nextstepHealthResult({status:'error',message:'无法连接健康数据，请重试'})}}
window.refreshHealthSteps=refreshHealthSteps;
window.nextstepHealthResult=value=>{
clearTimeout(healthTimer);healthPending=false;
if(value?.status==='ready'){
if(!Array.isArray(value.days)||value.days.length!==7||new Set(value.days.map(d=>d?.date)).size!==7||!value.days.every(d=>d&&validActivityDate(d.date)&&(d.steps===null||(Number.isSafeInteger(d.steps)&&d.steps>=0))&&(d.sources===undefined||(Array.isArray(d.sources)&&d.sources.every(s=>typeof s==='string'))))||!Array.isArray(value.sources)||!value.sources.every(s=>typeof s==='string')||(!Number.isFinite(value.syncedAt)||value.syncedAt<=0))value={status:'error',message:'步数数据格式无效，请重试'};
}
if(value?.status==='ready')saveStepRecords(value);
healthSteps=value&&['ready','permission','unavailable','error'].includes(value.status)?value:{status:'error',message:'无法读取健康数据'};updateHealthCard();
};
window.addEventListener('load',()=>refreshHealthSteps(false));
function saveLocal(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('浏览器存储不可用，请导出记录备份');return false}}
function toast(message){document.getElementById('toast').textContent=message;document.getElementById('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>document.getElementById('toast').classList.remove('visible'),3200)}
function navigate(page){if(page==='profile'){openSettings();return}if(page==='trends')page='training';if(!pages.some(p=>p[0]===page))page='today';location.hash=page;render(page)}
function heading(english,title,subtitle,action=''){return `<div class="page-heading"><div><p class="eyebrow">${english}</p><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action}</div>`}
function localDate(date=new Date()){return [date.getFullYear(),String(date.getMonth()+1).padStart(2,'0'),String(date.getDate()).padStart(2,'0')].join('-')}
function rangeStart(){const d=new Date();d.setHours(0,0,0,0);if(period==='month')d.setDate(1);else d.setDate(d.getDate()-(d.getDay()+6)%7);return d}
function rangeRecords(){return records.filter(r=>r.date>=localDate(rangeStart())&&r.date<=localDate())}
function summary(list){return {count:list.length,minutes:list.reduce((n,r)=>n+r.minutes,0),sets:list.reduce((n,r)=>n+r.sets,0),volume:list.reduce((n,r)=>n+r.volume,0)}}
function weeklyPlanProgress(){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-(d.getDay()+6)%7);return new Set(records.filter(r=>r.mode==='plan'&&(!r.activities?.length||r.items?.some(e=>e.sets.some(s=>s.done)))&&r.date>=localDate(d)&&r.date<=localDate()).map(r=>r.date)).size}
function strengthToday(){return records.some(r=>r.date===localDate()&&r.mode!=='sport'&&(!r.activities?.length||r.items?.some(e=>e.sets.some(s=>s.done))))}
function stats(){const a=summary(records.filter(r=>r.date===localDate())),b=summary(records.filter(r=>{const d=new Date();d.setDate(d.getDate()-(d.getDay()+6)%7);return r.date>=localDate(d)&&r.date<=localDate()}));const goal=Number(profile.frequency.match(/\d+/)?.[0])||4;return '<div class="stats-grid">'+[['今日训练',a.count,'次'],['今日时长',a.minutes,'分钟'],['本周训练',b.count,'次'],['计划完成',profile.trainingPlan?Math.min(100,Math.round(weeklyPlanProgress()/goal*100)):0,'％']].map(([label,value,unit])=>'<article class="stat"><div class="stat-head">'+label+'</div><div class="stat-number">'+value+'<small>'+unit+'</small></div><p class="stat-foot">'+(label==='计划完成'?'仅计划训练 · 同一天计一次':'根据已保存训练计算')+'</p></article>').join('')+'</div>'}
function chartBuckets(){const start=rangeStart(),count=period==='week'?7:new Date(start.getFullYear(),start.getMonth()+1,0).getDate(),step=period==='month'?7:1;const list=rangeRecords();return Array.from({length:Math.ceil(count/step)},(_,i)=>{const first=new Date(start),last=new Date(start);first.setDate(start.getDate()+i*step);last.setDate(start.getDate()+Math.min(count-1,i*step+step-1));const from=localDate(first),to=localDate(last);return {label:period==='week'?['一','二','三','四','五','六','日'][i]:(i*step+1)+'–'+Math.min(count,i*step+step),from,to,minutes:summary(list.filter(r=>r.date>=from&&r.date<=to)).minutes}})}
let calendarDate=localDate();
function monthDays(){const start=new Date();start.setDate(1);const count=new Date(start.getFullYear(),start.getMonth()+1,0).getDate();return Array.from({length:count},(_,i)=>{const d=new Date(start);d.setDate(i+1);const date=localDate(d),a=summary(records.filter(r=>r.date===date&&r.date<=localDate()));return {date,day:i+1,...a,level:a.minutes===0?0:a.minutes<20?1:a.minutes<40?2:a.minutes<60?3:4,future:date>localDate()}})}
function calendarDetail(date){const d=monthDays().find(d=>d.date===date);return d?'<strong>'+d.day+' 日</strong><span>'+(d.future?'尚未到来':d.count?d.count+' 次训练 · '+d.minutes+' 分钟':'暂无训练记录')+'</span>':''}
function monthlyCalendar(){const days=monthDays(),offset=(new Date(days[0].date+'T12:00:00').getDay()+6)%7;return '<div class="calendar-top"><div><span class="small-label">'+new Date().getFullYear()+' 年 '+(new Date().getMonth()+1)+' 月</span><div class="chart-total">'+summary(rangeRecords()).minutes+'<small>分钟</small></div></div><span class="calendar-count">'+days.filter(d=>d.count).length+' 天有训练</span></div><div class="training-calendar" aria-label="本月训练日历"><div class="calendar-weekdays">'+['一','二','三','四','五','六','日'].map(d=>'<span>'+d+'</span>').join('')+'</div><div class="calendar-grid">'+'<span class="calendar-blank" aria-hidden="true"></span>'.repeat(offset)+days.map(d=>'<button class="calendar-day heat-'+d.level+(d.future?' future':'')+(d.date===localDate()?' is-today':'')+'" data-calendar-date="'+d.date+'" aria-pressed="'+(d.date===calendarDate)+'" aria-label="'+d.date+'，'+(d.future?'尚未到来':d.count+' 次训练，'+d.minutes+' 分钟')+'"><span>'+d.day+'</span>'+(d.count?'<i aria-hidden="true"></i>':'')+'</button>').join('')+'</div></div><div class="calendar-legend"><span>训练时长</span>'+[['0','0'],['1','1–19'],['2','20–39'],['3','40–59'],['4','60+']].map(([level,label])=>'<span><i class="heat-'+level+'"></i>'+label+'</span>').join('')+'</div><div class="calendar-selection" aria-live="polite">'+calendarDetail(calendarDate)+'</div>'}
function selectCalendarDay(date){if(!monthDays().some(d=>d.date===date))return;calendarDate=date;const card=document.querySelector('.activity-card');if(!card)return;card.querySelectorAll('[data-calendar-date]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.calendarDate===date)));card.querySelector('.calendar-selection').innerHTML=calendarDetail(date)}
function bars(){if(period==='month')return monthlyCalendar();const values=chartBuckets(),max=Math.max(1,...values.map(v=>v.minutes));return '<div class="chart-top"><div class="chart-total">'+summary(rangeRecords()).minutes+'<small>分钟</small></div><span class="small-label">'+(period==='week'?'每日训练时长':'每 7 天汇总 · 分钟')+'</span></div><div class="bar-chart journal-chart" role="img" aria-label="'+(period==='week'?'本周每日训练时长':'本月按日期区间汇总时长')+'：'+values.map(v=>v.label+' '+v.minutes+'分钟').join('，')+'">'+values.map(v=>'<div class="bar-column"><div class="bar" style="height:'+v.minutes/max*112+'px" title="'+v.from+' 至 '+v.to+'：'+v.minutes+' 分钟"></div><small>'+v.label+'</small></div>').join('')+'</div>'}
function activityContent(){return '<div class="card-head"><h2>训练节奏</h2><div class="segmented" role="group" aria-label="统计时间范围"><button data-period="week" aria-pressed="'+(period==='week')+'" class="'+(period==='week'?'selected':'')+'">本周</button><button data-period="month" aria-pressed="'+(period==='month')+'" class="'+(period==='month'?'selected':'')+'">本月</button></div></div>'+bars()+'<p class="small-label" style="margin-top:13px">仅统计已保存的训练 · '+(period==='week'?'周一开始计周':'颜色表示当日训练分钟数 · 点击日期查看详情')+'</p>'}
function activityCard(){return '<section class="card activity-card">'+activityContent()+'</section>'}
function changePeriod(value){if(!['week','month'].includes(value)||period===value)return;period=value;const card=document.querySelector('.activity-card');if(!card)return;card.innerHTML=activityContent();if(currentPage==='training'){document.querySelector('.journal-metrics').innerHTML=journalMetrics();document.querySelector('.journal-period-records').innerHTML=journalPeriodRecords()}card.querySelector('[data-period="'+period+'"]').focus({preventScroll:true})}
function historyCard(){return `<section class="card"><div class="card-head"><h2>最近训练</h2><button class="text-button" data-page="training">全部记录</button></div>${historyRows(records.slice(0,3),false)}</section>`}
function historyRows(local){let html=local.map(r=>`<div class="history-row"><div class="history-day">${escapeHTML(r.date.slice(-2))}<small>${escapeHTML(r.date.slice(5,7))}月</small></div><div class="history-detail"><strong>${escapeHTML(r.name)}</strong><p>${r.mode==='sport'?'运动时长 · '+r.minutes+' 分钟 · 约 '+r.calories+' kcal':r.exercises+' 个动作 · '+r.sets+' 组 · '+r.minutes+' 分钟'}</p></div><div class="history-summary"><button class="text-button" data-record="${r.id}">查看详情</button><div class="record-actions"><button class="text-button" data-edit-record="${escapeHTML(r.id)}">编辑</button><button class="text-button danger-button" data-delete-record="${escapeHTML(r.id)}">删除</button></div><span>${r.mode==='sport'?'运动热量估算':r.volume.toLocaleString()+' kg 训练吨位'}</span></div></div>`).join('');return html||'<p class="empty">这个时间范围还没有训练记录，完成一次训练后即可查看趋势。</p>'}
function today(){const trained=strengthToday(),session=nextSession(),plannedToday=!!profile.trainingPlan?.days?.[(new Date().getDay()+6)%7]?.items.length;const label=draft?'正在进行的训练':plannedToday&&!trained?'今日训练内容':'下一次训练';const card=`<section class="home-workout"><div class="home-workout-copy"><div class="home-workout-label"><span class="icon-tile">${icon('dumbbell',20)}</span><span>${label}</span></div><h2>${escapeHTML((draft?(draft.name||'力量训练'):session?.name)||'按自己的节奏开练')}</h2><p class="subtitle">${draft?(draft.finishedAt?'训练已结束，待保存记录。':'训练计时中，随时回来继续。'):session?session.items.length+' 个动作 · 约 '+profile.duration+' 分钟 · '+escapeHTML(profile.goal):'自由选择动作，或完善资料后跟计划练。'}</p></div><div class="home-start"><button class="primary-button" data-action="start">${draft?(draft.finishedAt?'保存训练':'继续训练'):'开始训练'}</button><button class="text-button" data-page="plan">查看训练计划</button><button class="text-button" data-action="sport-setup">记录其他运动</button></div></section>`;return '<section class="home-overview">'+heading('TODAY',`你好，${escapeHTML(profile.name||'你')}。`,'',`<div class="date-chip">${escapeHTML(localDate())}</div>`)+(!trained||draft?card+stats():stats()+card)+healthCard()+'</section>'}
function journalMetrics(){const a=summary(rangeRecords());return [['训练次数',a.count,'次'],['累计时长',a.minutes,'分钟'],['完成组数',a.sets,'组'],['训练吨位',a.volume.toLocaleString(),'kg']].map(([label,value,unit])=>'<article class="stat"><div class="stat-head">'+label+'</div><div class="stat-number">'+value+'<small>'+unit+'</small></div></article>').join('')}
function journalPeriodRecords(){return '<div class="card-head"><h2>'+(period==='week'?'本周':'本月')+'训练记录</h2><button class="text-button" data-action="export">导出全部记录</button></div>'+historyRows(rangeRecords(),false)}
function training(){return heading('TRAINING & PROGRESS','每一次，都算数。','记录训练和每日活动，用真实数据看见积累。','<button class="primary-button" data-action="start">'+icon('play',16)+(draft?'继续训练':'记录训练')+'</button>')+stepHistory()+activityCard()+'<div class="stats-grid journal-metrics" style="margin-top:24px">'+journalMetrics()+'</div><section class="card journal-period-records">'+journalPeriodRecords()+'</section><details class="journal-all"><summary>全部历史记录（'+records.length+' 次）</summary><section class="card">'+historyRows(records,false)+'</section></details>'}
function recordDialog(id){const r=records.find(r=>String(r.id)===id);if(!r)return;openDialog(dialogHeader(escapeHTML(r.name))+(r.mode==='sport'?'<p class="subtitle">预估 '+r.calories+' kcal · MET '+r.met+' · 体重 '+r.bodyWeight+' kg'+(r.distance?' · '+r.distance+' 米':'')+' · 非实测</p>':'')+'<p class="subtitle">'+escapeHTML(r.date)+' · '+r.minutes+' 分钟 · '+r.sets+' 组 · '+r.volume.toLocaleString()+' kg</p><p class="subtitle">整体感受：'+escapeHTML(r.feeling||'未反馈')+'</p>'+sportDetails(r.activities)+(r.items||[]).map(e=>'<section class="record-exercise"><h3>'+escapeHTML(e.name)+'</h3><div class="table-scroll" role="region" aria-label="逐组训练数据" tabindex="0"><table class="set-table"><thead><tr><th>组</th><th>重量 kg</th><th>次数</th><th>感受</th></tr></thead><tbody>'+e.sets.filter(s=>s.done).map((s,i)=>'<tr><td>'+(i+1)+'</td><td>'+((e.type||exerciseInfo(e).type)==='bodyweight'?'—':escapeHTML(s.weight??'—'))+'</td><td>'+s.reps+'</td><td>'+escapeHTML(s.feel||'未反馈')+'</td></tr>').join('')+'</tbody></table></div></section>').join(''))}

function recordEditDialog(id){
 const r=records.find(r=>String(r.id)===String(id));if(!r)return;
 const field=(label,name,type,value,extra='')=>'<div class="field"><label for="edit-'+name+'">'+label+'</label><input id="edit-'+name+'" name="'+name+'" type="'+type+'" value="'+escapeHTML(value??'')+'" '+extra+' required></div>';
 let body=field('记录名称','name','text',r.name,'maxlength="80"')+field('训练日期','date','date',r.date,'max="'+localDate()+'"')+field('时长 / 分钟','minutes','number',r.minutes,'min="1" max="1440" step="1"');
 body+='<div class="field"><label for="edit-feeling">整体感受</label><select id="edit-feeling" name="feeling">'+['未反馈','轻松','合适','吃力'].map(f=>'<option '+(r.feeling===f?'selected':'')+'>'+f+'</option>').join('')+'</select></div>';
 if(r.mode==='sport')body+='<div class="field full"><label for="edit-sport">运动类型与强度</label><select id="edit-sport" name="sport">'+sports.map(s=>'<option value="'+s.id+'" '+(s.code===r.activityCode?'selected':'')+'>'+s.name+'</option>').join('')+'</select></div>'+field('记录时体重 / kg','weight','number',r.bodyWeight,'min="20" max="300" step="0.1"')+'<p class="small-label full">热量将根据运动类型、时长和体重重新估算。</p>';
 else body+=(r.activities||[]).map((a,i)=>'<section class="record-exercise full"><h3>'+escapeHTML(a.name)+'</h3>'+field('运动时长 / 分钟','activity-minutes-'+i,'number',a.minutes,'min="1" max="1440" step="1"')+field('记录时体重 / kg','activity-weight-'+i,'number',a.bodyWeight,'min="20" max="300" step="0.1"')+'<div class="field"><label for="edit-activity-distance-'+i+'">距离 / 米（可选）</label><input id="edit-activity-distance-'+i+'" name="activity-distance-'+i+'" type="number" min="1" max="1000000" step="1" value="'+escapeHTML(a.distance??'')+'"></div><p class="small-label">热量为含静息消耗的估算；运动时长与整次训练时长分别记录。</p></section>').join('')+(r.items||[]).map((e,i)=>'<section class="record-exercise full"><h3>'+escapeHTML(e.name)+'</h3>'+e.sets.map((s,j)=>!s.done?'':'<div class="record-set-edit"><span>第 '+(j+1)+' 组</span>'+((e.type||exerciseInfo(e).type)==='bodyweight'?'<span>次数训练</span>':field('重量 / kg','weight-'+i+'-'+j,'number',s.weight,'min="0.5" max="1000" step="0.5"'))+field('次数','reps-'+i+'-'+j,'number',s.reps,'min="1" max="100" step="1"')+'</div>').join('')+'</section>').join('');
 openDialog(dialogHeader('编辑历史记录')+'<form id="record-edit-form" data-id="'+escapeHTML(r.id)+'" class="profile-form">'+body+'<div class="full settings-actions"><button class="text-button" type="button" data-action="close">取消</button><button class="primary-button" type="submit">保存修改</button></div></form>');
}
function updateRecord(id,values){
 const original=records.find(r=>String(r.id)===String(id));if(!original)return false;
 const name=values.name?.trim(),minutes=Number(values.minutes),date=values.date;
 if(!name||name.length>80||!Number.isInteger(minutes)||minutes<1||minutes>1440||!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>localDate()||localDate(new Date(date+'T12:00:00'))!==date){toast('请填写有效的名称、日期和时长');return false}
 const next=JSON.parse(JSON.stringify(original));if(original.startedAt&&!next.workoutId)next.workoutId=String(original.startedAt);Object.assign(next,{name,date,minutes,feeling:values.feeling||'未反馈'});if(minutes!==original.minutes)next.seconds=minutes*60;
 if(next.startedAt&&(date!==original.date||minutes!==original.minutes)){const time=new Date(next.startedAt);const changed=new Date(date+'T00:00:00');changed.setHours(time.getHours(),time.getMinutes(),time.getSeconds(),time.getMilliseconds());next.startedAt=changed.getTime();next.endedAt=next.startedAt+(next.seconds??minutes*60)*1000}
 if(next.mode==='sport'){const sport=sports.find(s=>s.id===values.sport),calories=estimatedCalories(values.sport,minutes,Number(values.weight));if(!sport||calories===null){toast('请填写有效的运动类型和体重');return false}Object.assign(next,{calories,met:sport.met,activityCode:sport.code,bodyWeight:Number(values.weight)})}
 else {for(const [i,e] of (next.items||[]).entries())for(const [j,s] of e.sets.entries()){if(!s.done)continue;const bodyweight=(e.type||exerciseInfo(e).type)==='bodyweight',reps=Number(values['reps-'+i+'-'+j]),weight=bodyweight?null:Number(values['weight-'+i+'-'+j]);if(!Number.isInteger(reps)||reps<1||reps>100||(!bodyweight&&(!Number.isFinite(weight)||weight<=0||weight>1000))){toast('请填写有效的重量和整数次数');return false}Object.assign(s,{reps,weight})}if(next.items?.length){next.exercises=next.items.filter(e=>e.sets.some(s=>s.done)).length+(next.activities?.length||0);next.sets=next.items.flatMap(e=>e.sets).filter(s=>s.done).length;next.volume=next.items.reduce((n,e)=>n+e.sets.filter(s=>s.done).reduce((a,s)=>a+(s.weight||0)*s.reps,0),0)}}
 for(const [i,a] of (next.activities||[]).entries()){const duration=Number(values['activity-minutes-'+i]),weight=Number(values['activity-weight-'+i]),input=values['activity-distance-'+i],distance=input===''||input===undefined?null:Number(input);if(!Number.isInteger(duration)||duration<1||duration>1440||!Number.isFinite(weight)||weight<20||weight>300||(distance!==null&&(!Number.isInteger(distance)||distance<1||distance>1000000))){toast('请填写有效的运动时长、体重和距离');return false}Object.assign(a,{minutes:duration,seconds:duration*60,bodyWeight:weight,distance,calories:Math.round(a.met*weight*duration/60)})}if(next.mode!=='sport'&&(next.items?.length||next.activities?.length))next.exercises=(next.items||[]).filter(e=>e.sets.some(s=>s.done)).length+(next.activities?.length||0);
 const updated=records.map(r=>String(r.id)===String(id)?next:r).sort((a,b)=>b.date.localeCompare(a.date)||Number(b.id)-Number(a.id));if(!saveLocal('nextstep.records',updated))return false;records=updated;document.getElementById('workout-dialog').close();render();toast('记录已更新');return true;
}
function recordDeleteDialog(id){const r=records.find(r=>String(r.id)===String(id));if(!r)return;openDialog(dialogHeader('删除这条记录？')+'<p class="subtitle">'+escapeHTML(r.date)+' · '+escapeHTML(r.name)+'</p><p class="subtitle">删除后无法恢复，相关统计会同步更新。</p><div class="settings-actions"><button class="text-button" data-action="close">取消</button><button class="primary-button danger-button" data-confirm-delete="'+escapeHTML(r.id)+'">确认删除</button></div>')}
function deleteRecord(id){if(!records.some(r=>String(r.id)===String(id)))return false;const next=records.filter(r=>String(r.id)!==String(id));if(!saveLocal('nextstep.records',next))return false;records=next;document.getElementById('workout-dialog').close();render();toast('记录已删除');return true}

const exerciseCatalog=[
['椅子深蹲','下肢','徒手',null],['墙壁俯卧撑','胸部','徒手',null],['俯卧撑','胸部','徒手',null],['臀桥','臀部','徒手',null],['站姿提踵','小腿','徒手',null],['侧卧抬腿','髋部','徒手',null],['卷腹','核心','徒手',null],['反向卷腹','核心','徒手',null],
['哑铃高脚杯深蹲','下肢','哑铃',5],['哑铃卧推','胸部','哑铃',2.5],['上斜哑铃卧推','胸部','哑铃',2.5],['哑铃划船','背部','哑铃',5],['哑铃罗马尼亚硬拉','下肢','哑铃',5],['哑铃弯举','手臂','哑铃',2.5],['哑铃侧平举','肩部','哑铃',1],['哑铃肩推','肩部','哑铃',2.5],
['杠铃卧推','胸部','杠铃',5],['杠铃深蹲','下肢','杠铃',5],['杠铃划船','背部','杠铃',5],['杠铃罗马尼亚硬拉','下肢','杠铃',5],
['器械腿举','下肢','固定器械',5],['器械推胸','胸部','固定器械',5],['高位下拉','背部','固定器械',5],['坐姿划船','背部','固定器械',5],['腿弯举','下肢','固定器械',5],['腿屈伸','下肢','固定器械',5],['器械肩推','肩部','固定器械',5],
['绳索下压','手臂','绳索',2.5],['绳索面拉','肩部','绳索',2.5],['绳索夹胸','胸部','绳索',2.5],['壶铃硬拉','下肢','壶铃',4],['壶铃高脚杯深蹲','下肢','壶铃',4],['弹力带划船','背部','弹力带',null],['弹力带推胸','胸部','弹力带',null],['弹力带侧平举','肩部','弹力带',null]
].map(([name,muscle,equipment,reference])=>({name,muscle,equipment,reference,type:reference===null?'bodyweight':'weighted'}));
function exerciseInfo(e){return exerciseCatalog.find(x=>x.name===e.name)||{...e,type:e.type||'weighted',reference:2.5,equipment:'自选'}}
function recommendedWeight(e){const info=exerciseInfo(e);if((e.type||info.type)==='bodyweight')return {weight:null,source:'次数训练，无需填写 kg'};for(const record of records){const old=record.items?.find(x=>x.name===e.name);const set=old?.sets?.findLast(x=>x.done&&Number(x.weight)>0);if(set)return {weight:Number(set.weight),source:'来自最近完成的同名动作'}}return {weight:info.reference||2.5,source:'轻负重试练参考，按实际器械与能力确认；杠铃含杆重，哑铃按单只'}}
function makeWorkoutItem(e){const info=exerciseInfo(e),type=e.type||info.type,reference=recommendedWeight({...e,type});return {name:e.name,muscle:e.muscle||info.muscle,type,equipment:info.equipment,sets:Array.from({length:e.sets||3},()=>({weight:reference.weight,reps:e.reps||10,feel:'未反馈',done:false}))}}
const sports=[['stairs-slow','爬楼 · 慢速',4.5,'17133'],['stairs','爬楼 · 一般速度',6.8,'17131'],['stairs-fast','爬楼 · 快速',9.3,'17134'],['swim-slow','游泳 · 自由泳轻松游',5.8,'18240'],['swim-fast','游泳 · 自由泳快速',9.8,'18230'],['swim-breast','游泳 · 蛙泳休闲',5.3,'18265'],['swim-back','游泳 · 仰泳休闲',4.8,'18255'],['surf','冲浪 · 一般',3,'18220'],['surf-paddle','冲浪板划水',6.8,'18221'],['sup','桨板 · 一般',6.5,'18224'],['kayak','皮划艇 · 中等强度',5,'18100'],['walk','步行 · 一般速度',3.8,'17190'],['walk-brisk','步行 · 快走',4.8,'17200'],['hike','徒步 · 一般速度',5.3,'17082'],['jog','慢跑 · 自选速度',7.5,'12020']].map(([id,name,met,code])=>({id,name,met,code}));
function estimatedCalories(id,minutes,weight){const sport=sports.find(x=>x.id===id);if(!sport||!Number.isFinite(Number(minutes))||minutes<=0||minutes>1440||!Number.isFinite(Number(weight))||weight<20||weight>300)return null;return Math.round(sport.met*weight*minutes/60)}
function startSession(){if(draft){workoutDialog();return false}const next={mode:'free',name:'我的训练',manualEnd:true,startedAt:Date.now(),restSeconds:defaultRestSeconds(),restEnd:0,items:[],activities:[]};if(!saveLocal('nextstep.draft',next))return false;draft=next;selectedExercise=0;restEnd=0;workoutDialog();render();return true}
function sessionActions(){return '<div class="card-actions"><button class="secondary-button" data-action="free-setup">添加力量 / 次数动作</button><button class="secondary-button" data-action="sport-setup">添加跑步 / 游泳等运动</button></div><p class="small-label">同一次训练内的动作统一保存，只计一次训练。总时长包含休息；运动时长单独记录。</p>'}
function sportDetails(activities){return (activities||[]).map(a=>'<section class="record-exercise"><h3>'+escapeHTML(a.name)+'</h3><p class="subtitle">'+a.minutes+' 分钟'+(a.distance?' · '+a.distance+' 米':'')+' · 约 '+a.calories+' kcal（含静息消耗的估算）</p><p class="small-label">MET '+a.met+' · 体重 '+a.bodyWeight+' kg · 非实测</p></section>').join('')}
function projectOptions(mode){return mode==='sport'?sports.map(e=>({key:e.id,name:e.name,group:e.name.split(' · ')[0],meta:'MET '+e.met,search:e.name+' '+(e.id==='jog'?'跑步 有氧':e.id.startsWith('walk')?'走路 步行 有氧':e.id.startsWith('stairs')?'楼梯 爬楼 有氧':'有氧')})):exerciseCatalog.map(e=>({key:e.name,name:e.name,group:e.equipment,meta:e.equipment+' · '+e.muscle+' · '+(e.type==='bodyweight'?'次数训练':'负重训练'),search:e.name+' '+e.equipment+' '+e.muscle+' '+(e.type==='bodyweight'?'自重 徒手 次数':'重量 负重')}))}
function recentProjectKeys(mode){const list=draft?[draft,...records]:records,keys=[];for(const r of list){const entries=mode==='sport'?(r.mode==='sport'?[r]:r.activities||[]):(r.items||[]).filter(e=>e.sets?.some(s=>s.done));for(const e of entries){const key=mode==='sport'?sports.find(x=>x.code===e.activityCode)?.id:e.name;if(key&&!keys.includes(key))keys.push(key)}}return keys}
function matchingProjects(mode,query='',group=''){const words=String(query).trim().toLowerCase().split(/\s+/).filter(Boolean),recent=recentProjectKeys(mode);return projectOptions(mode).filter(e=>(!group||e.group===group)&&words.every(w=>e.search.toLowerCase().includes(w))).sort((a,b)=>{const ai=recent.indexOf(a.key),bi=recent.indexOf(b.key);return (ai<0?recent.length:ai)-(bi<0?recent.length:bi)})}
function projectResults(mode,query='',group=''){const list=matchingProjects(mode,query,group),recent=recentProjectKeys(mode);return '<p class="project-count" role="status">'+(list.length?'找到 '+list.length+' 个项目 · 最近使用优先':'没有匹配的项目，试试其他关键词或分类')+'</p><div class="project-results">'+list.map(e=>'<button type="button" class="project-option" data-project-mode="'+mode+'" data-project-key="'+escapeHTML(e.key)+'"><span><strong>'+escapeHTML(e.name)+'</strong><small>'+escapeHTML(e.meta)+'</small></span>'+(recent.includes(e.key)?'<span class="project-recent">最近</span>':'')+'</button>').join('')+'</div>'+(mode==='free'&&!list.length?'<p class="small-label">也可以在下方「动作名称」中填写自定义动作。</p>':'')}
function projectPicker(mode){const groups=[...new Set(projectOptions(mode).map(e=>e.group))];return '<section class="project-picker full" aria-label="快速查找训练项目"><div class="project-search-fields"><div class="field"><label for="project-search-'+mode+'">搜索项目</label><input id="project-search-'+mode+'" type="search" data-project-search="'+mode+'" placeholder="'+(mode==='sport'?'如：跑步、游泳、爬楼':'如：划船、背部、哑铃')+'" autocomplete="off"></div><div class="field"><label for="project-group-'+mode+'">'+(mode==='sport'?'运动分类':'器械分类')+'</label><select id="project-group-'+mode+'" data-project-group="'+mode+'"><option value="">全部</option>'+groups.map(g=>'<option>'+escapeHTML(g)+'</option>').join('')+'</select></div></div><div id="project-results-'+mode+'">'+projectResults(mode)+'</div></section>'}
function updateProjectPicker(mode){document.getElementById('project-results-'+mode).innerHTML=projectResults(mode,document.getElementById('project-search-'+mode).value,document.getElementById('project-group-'+mode).value)}
function chooseProject(mode,key){if(mode==='swap'){replaceExercise(key);return}const select=document.getElementById(mode==='sport'?'sport-type':'free-catalog');if(!projectOptions(mode).some(e=>e.key===key))return;select.value=key;if(mode==='sport')persistSetInput({target:select,type:'change'});else updateFreeForm(select);const target=document.getElementById(mode==='sport'?'sport-minutes':'free-name');target.focus();}
function sportSetup(back=draft?'back-workout':'back-mode'){openTrainingForm(dialogHeader(draft?'添加其他运动':'记录运动',back)+`<form id="sport-form" class="profile-form">${projectPicker('sport')}<div class="field full"><label for="sport-type">运动类型与强度</label><select id="sport-type" name="sport">${sports.map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}</select></div><div class="field"><label for="sport-minutes">实际运动时长 / 分钟</label><input id="sport-minutes" name="minutes" type="number" min="1" max="1440" required></div><div class="field"><label for="sport-weight">当前体重 / kg</label><input id="sport-weight" name="weight" type="number" min="20" max="300" step="0.1" value="${escapeHTML(profile.weight)}" required></div><div class="field"><label for="sport-distance">距离 / 米（可选）</label><input id="sport-distance" name="distance" type="number" min="1" max="1000000" step="1"></div><div class="field full"><label for="sport-date">运动日期</label><input id="sport-date" name="date" type="date" max="${localDate()}" value="${draft?localDate(new Date(draft.startedAt)):localDate()}" ${draft?'readonly':''} required></div><div class="full calorie-preview" id="sport-estimate" aria-live="polite">填写时长和体重后显示预估热量</div><p class="full small-label">按 MET × 体重 × 小时估算总消耗（含静息消耗），不是实测；运动时长请排除休息。来源：<a href="https://pacompendium.com/" target="_blank" rel="noopener">2024 体力活动汇编</a>，成人 19–59 岁参考值。</p><button class="full primary-button" type="submit">${draft?'添加并返回训练':'保存运动记录'}</button></form>`)}
function saveSport(values){const sport=sports.find(x=>x.id===values.sport),calories=estimatedCalories(values.sport,Number(values.minutes),Number(values.weight));if(!sport||calories===null||!/^\d{4}-\d{2}-\d{2}$/.test(values.date)||values.date>localDate()||localDate(new Date(values.date+'T12:00:00'))!==values.date){toast('请填写有效的运动时长、体重和日期');return false}const distance=values.distance===''||values.distance===undefined?null:Number(values.distance);if(distance!==null&&(!Number.isInteger(distance)||distance<1||distance>1000000)){toast('请填写有效的整数距离');return false}const record={id:Date.now(),distance,mode:'sport',name:sport.name,date:values.date,minutes:Number(values.minutes),seconds:Number(values.minutes)*60,exercises:0,sets:0,volume:0,items:[],calories,met:sport.met,activityCode:sport.code,bodyWeight:Number(values.weight),calorieMethod:'MET × kg × hours (gross)',source:'https://pacompendium.com/'};if(draft){if(values.date!==localDate(new Date(draft.startedAt))){toast('运动日期应与本次训练开始日期一致');return false}const nextDraft={...draft,manualEnd:true,activities:[...(draft.activities||[]),record]};delete nextDraft.finishedAt;if(!saveLocal('nextstep.draft',nextDraft))return false;draft=nextDraft;workoutDialog();render();toast('运动已加入本次训练，结束后统一保存');return true}const next=[record,...records];if(!saveLocal('nextstep.records',next))return false;records=next;document.getElementById('workout-dialog').close();render();toast('运动记录已保存，热量为估算值');return true}
const settingsChoices={goal:['增肌','减脂','提升体能','保持健康'],frequency:['每周 2 次','每周 3 次','每周 4 次','每周 5 次'],lifestyle:['久坐为主','经常走动','体力劳动'],experience:['刚开始','有训练基础'],duration:['20','30','45','60'],equipment:['徒手 / 家中','哑铃','健身房','杠铃','壶铃','弹力带','固定器械','绳索']};
function generatePlan(p){const count=Number(p.frequency.match(/\d+/)[0]),days={2:[0,3],3:[0,2,5],4:[0,1,3,5],5:[0,1,3,4,6]}[count];const sets=p.experience==='刚开始'||p.duration==='20'||p.lifestyle==='体力劳动'?2:3;const reps=p.goal==='增肌'?10:12;const home=[['椅子深蹲','下肢'],['墙壁俯卧撑','上肢推'],['臀桥','臀部'],['站姿提踵','小腿']];const dumbbell=[['哑铃高脚杯深蹲','下肢'],['哑铃卧推','上肢推'],['哑铃划船','上肢拉'],['哑铃罗马尼亚硬拉','下肢']];const gym=[['器械腿举','下肢'],['器械推胸','上肢推'],['高位下拉','上肢拉'],['坐姿划船','上肢拉']];const pool=p.equipment==='健身房'?exerciseCatalog.filter(e=>e.type==='weighted').map(e=>[e.name,e.muscle]):p.equipment==='哑铃'?dumbbell:p.equipment==='徒手 / 家中'?home:exerciseCatalog.filter(e=>e.equipment===p.equipment).map(e=>[e.name,e.muscle]);return {generatedAt:Date.now(),days:Array.from({length:7},(_,day)=>{const index=days.indexOf(day);if(index<0)return {name:'休息与自由活动',items:[]};let chosen=p.equipment==='健身房'?['下肢','胸部','背部','肩部'].map(m=>{const group=pool.filter(e=>e[1]===m);return group[index%group.length]}):pool.slice(0,4);if(index%2)chosen=chosen.slice(2).concat(chosen.slice(0,2));if(p.duration==='20')chosen=chosen.slice(0,3);if(p.duration==='60'){const extra=exerciseCatalog.find(e=>(p.equipment==='健身房'?e.type==='weighted':p.equipment==='徒手 / 家中'?e.equipment==='徒手':e.equipment===p.equipment)&&!chosen.some(c=>c[0]===e.name));if(extra)chosen.push([extra.name,extra.muscle])}return {name:'全身训练 '+(index%2?'B':'A'),items:chosen.map(([name,muscle])=>({name,muscle,english:muscle,type:exerciseInfo({name}).type,weight:recommendedWeight({name}).weight,reps,sets:p.duration==='30'?Math.min(sets,2):sets}))}})}}
function changePlanDay(day){if(!Number.isInteger(day)||day<0||day>6||currentPage!=='plan')return;planDay=day;const app=document.getElementById('app'),container=app.querySelector?.('.page-enter');if(!container){render();return}const oldDays=container.querySelector('.plan-days'),oldGrid=container.querySelector('.wide-grid');if(!oldDays||!oldGrid)return;const template=document.createElement('template');template.innerHTML=plan();oldDays.replaceWith(template.content.querySelector('.plan-days'));oldGrid.replaceWith(template.content.querySelector('.wide-grid'));container.querySelector('[data-day="'+day+'"]').focus({preventScroll:true})}
function selectedSession(){return profile.trainingPlan?.days?.[planDay]||null}
function nextSession(){const days=profile.trainingPlan?.days;if(!days)return null;const today=(new Date().getDay()+6)%7;for(let i=strengthToday()?1:0;i<8;i++){const session=days[(today+i)%7];if(session.items.length)return session}return null}
function reminderBanner(){if(!reminderReason||reminderDismissed)return '';return `<section class="profile-reminder"><div><strong>${reminderReason==='first'?'欢迎，先建立你的训练节奏':'欢迎回来，更新一下当前状态'}</strong><p>${reminderReason==='first'?'补充身高、体重、生活方式和目标，生成你的第一份计划。':'已有 30 天未使用，确认身体信息、生活方式和目标是否有变化。'}</p></div><button class="secondary-button" data-action="settings">${reminderReason==='first'?'开始设置':'更新资料'}</button></section>`}
function plan(){const session=selectedSession(),ready=!!profile.trainingPlan;return heading('YOUR NEXT STEP','适合现在的你。','基础信息与每周计划，在这里一起维护。',`<button class="secondary-button" data-action="settings">${icon('user',16)} 设置</button>`)+(ready?`<div class="plan-summary"><span>${escapeHTML(profile.goal)}</span><span>${escapeHTML(profile.frequency)}</span><span>${escapeHTML(profile.duration)} 分钟 / 次</span><span>${escapeHTML(profile.equipment)}</span></div><div class="plan-days">${['一','二','三','四','五','六','日'].map((d,i)=>`<button class="day ${i===planDay?'active':''}" data-day="${i}" aria-pressed="${i===planDay}">周${d}<b>${profile.trainingPlan.days[i].items.length?'练':'休'}</b></button>`).join('')}</div><div class="wide-grid"><section class="card"><div class="card-head"><h2>${escapeHTML(session.name)}</h2><span class="pill">${session.items.length?'力量训练':'恢复日'}</span></div>${session.items.length?`<div class="exercise-list">${session.items.map((e,i)=>`<div class="exercise-row"><span class="exercise-index">${i+1}</span><div class="exercise-info"><strong>${escapeHTML(e.name)}</strong><small>${escapeHTML(e.muscle)}</small></div><div class="exercise-amount">${e.sets} 组 × ${e.reps} 次<small>${(e.type||exerciseInfo(e).type)==='bodyweight'?'次数训练':'参考 '+recommendedWeight(e).weight+' kg · 现场确认'}</small></div></div>`).join('')}</div><div class="card-actions"><button class="primary-button" data-action="start">${draft?'继续进行中的训练':'开始这次训练'}</button></div>`:'<p class="empty">今天留给休息，也可以按状态自由活动。</p>'}</section><section class="card"><h2>计划依据</h2><div class="list-row">生活方式<span>${escapeHTML(profile.lifestyle)}</span></div><div class="list-row">训练经验<span>${escapeHTML(profile.experience)}</span></div><div class="list-row">资料更新<span>${localDate(new Date(profile.updatedAt))}</span></div><p class="subtitle">${profile.goal==='减脂'?'力量训练外，预留步行等日常活动时间。':profile.goal==='提升体能'?'以规律训练与动作熟练度为重点。':profile.goal==='保持健康'?'保持可持续的训练节奏，留出恢复时间。':'按动作质量完成各组，训练重量由你现场确认。'}</p><div class="soft-note">${profile.lifestyle==='体力劳动'?'考虑日常体力负荷，初始计划减少每个动作的组数。':'计划根据目标、经验、器械、频率和单次时间生成。'} 身高体重用于资料维护，不直接决定训练负重。</div><button class="text-button" style="margin-top:16px" data-action="settings">修改资料与计划</button></section></div>`:`<section class="card empty"><h2>你的计划，从当前状态开始</h2><p class="subtitle">设置目标、训练时间和可用器械，自动安排一周训练。</p><button class="primary-button" style="margin-top:20px" data-action="settings">完善资料并生成计划</button></section>`)}
function selectField(key,label){return `<div class="field"><label for="${key}">${label}</label><select id="${key}" name="${key}" required><option value="" disabled ${profile[key]?'':'selected'}>请选择</option>${settingsChoices[key].map(value=>`<option value="${escapeHTML(value)}" ${String(profile[key])===value?'selected':''}>${value}${key==='duration'?' 分钟':''}</option>`).join('')}</select></div>`}
function appUpdateSettings(){return window.NextStepAndroid&&typeof window.NextStepAndroid.openAppUpdates==='function'?'<section class="app-update-settings"><h3>应用更新</h3><p class="subtitle">检查新版、自动下载和安装更新。</p><button class="secondary-button" data-action="app-updates">检查更新 / 自动更新</button></section>':''}
function openSettings(){openDialog(dialogHeader(reminderReason&&!reminderDismissed?(reminderReason==='first'?'先认识现在的你':'欢迎回来，确认当前状态'):'个人资料与训练设置')+`<p class="subtitle">保存后自动生成每周计划，已记录的训练和进行中的草稿会保留。</p><form id="profile-form" class="profile-form" style="margin-top:24px"><div class="field full"><label for="name">称呼</label><input id="name" name="name" required maxlength="20" value="${escapeHTML(profile.name)}"></div><div class="field"><label for="height">身高 / cm</label><input id="height" name="height" type="number" required min="100" max="250" step="0.1" value="${escapeHTML(profile.height)}"></div><div class="field"><label for="weight">当前体重 / kg</label><input id="weight" name="weight" type="number" required min="20" max="300" step="0.1" value="${escapeHTML(profile.weight)}"></div>${selectField('lifestyle','日常生活方式')}${selectField('goal','追求目标')}${selectField('experience','训练经验')}${selectField('equipment','可用器械')}${selectField('frequency','每周训练频率')}${selectField('duration','单次可用时间')}<div class="full card-actions settings-actions"><button class="primary-button" type="submit">保存并生成计划</button><button class="text-button" type="button" data-action="dismiss-reminder">稍后再说</button></div></form><details class="journal-all"><summary>数据与备份</summary><p class="subtitle">资料、计划和记录保存在当前设备。</p><button class="secondary-button" data-action="export">导出全部资料与训练记录</button></details>${appUpdateSettings()}`)}
function saveProfile(values){if(!values.name?.trim()||values.name.trim().length>20||!Number.isFinite(Number(values.height))||Number(values.height)<100||Number(values.height)>250||!Number.isFinite(Number(values.weight))||Number(values.weight)<20||Number(values.weight)>300||Object.entries(settingsChoices).some(([key,choices])=>!choices.includes(values[key]))){toast('请填写完整且有效的资料');return false}const next={...profile,...values,name:values.name.trim(),height:Number(values.height),weight:Number(values.weight),updatedAt:Date.now()};next.trainingPlan=generatePlan(next);if(!saveLocal('nextstep.profile',next))return false;profile=next;reminderReason='';reminderDismissed=false;planDay=next.trainingPlan.days.findIndex(d=>d.items.length);return true}
function render(page=currentPage){if(page==='profile'){page='plan';openSettings()}if(page==='trends')page='training';currentPage=page;document.getElementById('breadcrumb').textContent=pages.find(p=>p[0]===page)?.[1]||'今日概览';const nav=pages.map(([id,label,ic])=>`<button class="nav-item ${id===page?'active':''}" data-page="${id}" ${id===page?'aria-current="page"':''}>${icon(ic,20)}<span>${label}</span></button>`).join('');document.getElementById('navigation').innerHTML=nav;document.getElementById('mobile-navigation').innerHTML=nav;document.getElementById('sidebar-count').textContent=`${weeklyPlanProgress()} / ${Number(profile.frequency.match(/\d+/)?.[0])||4} 次`;document.querySelector('.progress i').style.width=Math.min(100,Number(document.getElementById('sidebar-count').textContent.split('/')[0])/(Number(profile.frequency.match(/\d+/)?.[0])||4)*100)+'%';if(!profile.updatedAt)document.getElementById('sidebar-count').textContent='尚未设置目标';document.getElementById('app').innerHTML=`<div class="page-enter">${reminderBanner()}${({today,training,plan}[page]||today)()}</div>`}
function openDialog(content){document.getElementById('workout-content').innerHTML=`<div class="dialog-content">${content}</div>`;if(!document.getElementById('workout-dialog').open)document.getElementById('workout-dialog').showModal()}
function dialogHeader(title,back='',backLabel='返回'){return `<div class="dialog-header"><h2 id="workout-title">${title}</h2>${back?`<button class="text-button" data-action="${back}">${escapeHTML(backLabel)}</button>`:''}<button class="close-button" data-action="close" aria-label="关闭窗口">${icon('close',17)}</button></div>`}
function defaultRestSeconds(){return [60,90,120,180].includes(Number(profile.restSeconds))?Number(profile.restSeconds):90}
function restSelector(){return '<div class="field full"><label for="workout-rest">组间休息</label><select id="workout-rest">'+[60,90,120,180].map(n=>'<option value="'+n+'" '+(n===(draft?.restSeconds||defaultRestSeconds())?'selected':'')+'>'+n+' 秒</option>').join('')+'</select><p class="small-label">调整用于下一次休息，不改变正在进行的倒计时。</p></div>'}
function workoutModeDialog(){if(draft){workoutDialog();return}const session=currentPage==='plan'?selectedSession():nextSession();openDialog(dialogHeader('选择训练方式')+`${restSelector()}<div class="mode-options"><section class="mode-card"><span class="pill">一次完整训练</span><h3>从进场到结束，记一次</h3><p class="subtitle">开始计时后，可以陆续添加力量、次数、跑步、游泳等动作，结束时统一保存。</p><button class="primary-button" data-action="start-session">开始一次训练</button></section><section class="mode-card"><span class="pill">跟计划练</span><h3>${session?.items.length?escapeHTML(session.name):'先建立训练计划'}</h3><p class="subtitle">${session?.items.length?session.items.length+' 个动作 · 完成一组后自动开始休息倒计时':'在设置中完善资料，生成适合你的训练安排。'}</p><button class="primary-button" data-action="${session?.items.length?'start-plan':'settings'}">${session?.items.length?'开始计划训练':'设置训练计划'}</button></section><section class="mode-card"><span class="pill">自由训练</span><h3>今天，自己安排</h3><p class="subtitle">自己选择动作、组数和次数，同样记录时长和逐组表现。</p><button class="secondary-button" data-action="free-setup">选择动作并开始</button></section><section class="mode-card"><span class="pill">其他运动</span><h3>爬楼、游泳、冲浪等</h3><p class="subtitle">记录运动时长与预估热量。</p><button class="secondary-button" data-action="sport-setup">记录运动与热量</button></section></div><p class="small-label">点击开始后计时；休息时间计入本次训练时长。</p>`)}
function startWorkout(){if(!draft){const session=currentPage==='plan'?selectedSession():nextSession();if(!session?.items.length){openSettings();return}selectedExercise=0;const next={mode:'plan',name:session.name,startedAt:Date.now(),restSeconds:defaultRestSeconds(),restEnd:0,items:session.items.map(makeWorkoutItem)};if(!saveLocal('nextstep.draft',next))return;draft=next;restEnd=0}workoutDialog();render()}
function freeSetup(back=draft?'back-workout':'back-mode'){openTrainingForm(dialogHeader(draft?'添加力量动作':'自由训练 · 选择动作',back)+`<form id="free-form" class="profile-form">${projectPicker('free')}<details class="project-all full"><summary>全部动作 / 自定义</summary><div class="field full"><label for="free-catalog">动作与器械库</label><select id="free-catalog"><option value="">自定义动作</option>${exerciseCatalog.map(e=>`<option value="${e.name}">${e.equipment} · ${e.name}</option>`).join('')}</select></div></details><div class="field full"><label for="free-name">动作名称</label><input id="free-name" name="exercise" required maxlength="40" placeholder="选择动作，或输入名称"></div><div class="field full"><label for="free-type">记录类型</label><select id="free-type" name="type"><option value="weighted">负重训练（kg）</option><option value="bodyweight">自重 / 弹力带（记录次数）</option></select></div><div class="field"><label for="free-sets">组数</label><input id="free-sets" name="sets" type="number" min="1" max="20" value="3" required></div><div class="field"><label for="free-reps">每组次数</label><input id="free-reps" name="reps" type="number" min="1" max="100" value="10" required></div><div class="field full" id="free-weight-field"><label for="free-weight">实际重量 / kg</label><input id="free-weight" name="weight" type="number" min="0.5" max="1000" step="0.5" required><p class="small-label" id="free-weight-note">负重组不能记录0 kg，请按实际重量填写。</p></div>${draft?'':restSelector()}<div class="full settings-actions"><button class="primary-button" type="submit">${draft?'添加并返回训练':'开始自由训练'}</button></div></form>`)}
function updateFreeForm(el){const name=document.getElementById('free-name'),type=document.getElementById('free-type'),weight=document.getElementById('free-weight');if(el.id==='free-catalog'&&el.value){const info=exerciseCatalog.find(e=>e.name===el.value);name.value=info.name;type.value=info.type;const reference=recommendedWeight(info);weight.value=reference.weight??'';document.getElementById('free-weight-note').textContent=reference.source}const body=type.value==='bodyweight';document.getElementById('free-weight-field').hidden=body;weight.disabled=body;weight.required=!body}
function startFreeWorkout(values){const name=values.exercise?.trim(),sets=Number(values.sets),reps=Number(values.reps),type=values.type||exerciseInfo({name}).type,weight=type==='bodyweight'?null:Number(values.weight);if(!name||name.length>40||!['weighted','bodyweight'].includes(type)||!Number.isInteger(sets)||sets<1||sets>20||!Number.isInteger(reps)||reps<1||reps>100||(type==='weighted'&&(values.weight===''||!Number.isFinite(weight)||weight<=0||weight>1000))){toast('请填写有效的动作、组数、次数；负重必须大于0 kg');return false}const item={name,muscle:exerciseInfo({name}).muscle||'自由训练',type,sets:Array.from({length:sets},()=>({weight,reps,feel:'未反馈',done:false}))};const next=draft?{...draft,items:[...draft.items,item]}:{mode:'free',name:'自由训练',startedAt:Date.now(),restSeconds:defaultRestSeconds(),restEnd:0,items:[item]};delete next.finishedAt;next.activeExercise=next.items.length-1;if(!saveLocal('nextstep.draft',next))return false;draft=next;selectedExercise=draft.items.length-1;draft.activeExercise=selectedExercise;workoutDialog();render();return true}
function pendingSet(){if(!draft)return null;let index=selectedExercise,exercise=draft.items[index],set=exercise?.sets.findIndex(s=>!s.done);if(set===undefined||set<0){index=draft.items.findIndex(e=>e.sets.some(s=>!s.done));if(index<0)return null;exercise=draft.items[index];set=exercise.sets.findIndex(s=>!s.done)}return {exerciseIndex:index,exercise,setIndex:set,set:exercise.sets[set]}}
function completeSet(index){if(!draft||draft.paused)return;const current=pendingSet();if(!current||current.exerciseIndex!==selectedExercise||current.setIndex!==index||restEnd>Date.now())return;if((current.exercise.type||exerciseInfo(current.exercise).type)!=='bodyweight'&&!(current.set.weight>0)){toast('负重训练必须填写大于0 kg的实际重量');return}const next=JSON.parse(JSON.stringify(draft));const set=next.items[selectedExercise].sets[index];if((current.exercise.type||exerciseInfo(current.exercise).type)==='bodyweight')set.weight=null;set.done=true;set.completedAt=Date.now();const remaining=next.items.some(e=>e.sets.some(s=>!s.done));next.restEnd=remaining?Date.now()+(next.restSeconds||90)*1000:0;next.restSet=selectedExercise+':'+index;next.activeExercise=selectedExercise;if(!saveLocal('nextstep.draft',next))return;draft=next;restEnd=next.restEnd;workoutDialog()}
function endRest(){if(!draft||draft.paused)return;const next={...draft,restEnd:0};if(!saveLocal('nextstep.draft',next))return;draft=next;restEnd=0;workoutDialog()}
function elapsedText(){const seconds=draft?Math.max(0,Math.floor(((draft.finishedAt||Date.now())-draft.startedAt)/1000)):0;return [Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(n=>String(n).padStart(2,'0')).join(':')}
function extendRest(){if(!draft||draft.paused||restEnd<=Date.now())return;const next={...draft,restEnd:restEnd+30000};if(!saveLocal('nextstep.draft',next))return;draft=next;restEnd=next.restEnd;workoutDialog()}
function finishReview(){if(!draft)return;const count=draft.items.flatMap(e=>e.sets).filter(s=>s.done).length;if(!count&&!draft.activities?.length){toast('先完成一组或添加一项运动');return}if(!draft.finishedAt){const next={...draft,finishedAt:Date.now()};if(!saveLocal('nextstep.draft',next))return;draft=next}openDialog(dialogHeader('训练结束')+`<div class="finished-step"><span class="step-kicker">已完成 ${count} 组 · ${draft.activities?.length||0} 项运动 · ${elapsedText()}</span><h3>这次训练感觉怎么样？</h3><p class="subtitle">回顾整体感受，方便下次调整。</p><div class="workout-feelings" role="group" aria-label="本次训练整体感受">${['轻松','合适','吃力'].map(f=>`<button class="feeling-button" data-workout-feel="${f}" aria-pressed="${draft.feedback===f}">${f}</button>`).join('')}</div><button class="primary-button" data-action="save-workout">保存训练</button><p class="small-label" style="margin-top:12px">感受可选，也可以直接保存。</p><button class="text-button" data-action="workout-options">检查 / 修改记录</button>${pendingSet()||draft.manualEnd?'<button class="text-button" data-action="resume-workout">返回继续训练</button>':draft.mode==='free'?'<button class="text-button" data-action="free-setup">再添加一个动作</button>':''}</div>`)}
function toggleWorkoutPause(){if(!draft||draft.finishedAt)return false;cancelEndHold();const paused=!draft.paused,next={...draft,paused};if(paused){next.pausedRest=Math.max(0,restEnd-Date.now());next.restEnd=0}else{next.restEnd=next.pausedRest>0?Date.now()+next.pausedRest:0;delete next.pausedRest}if(!saveLocal('nextstep.draft',next))return false;draft=next;restEnd=next.restEnd;workoutDialog();return true}
function workoutDialog(){if(!draft)return;if(draft.finishedAt){finishReview();return}const current=pendingSet();if(current)selectedExercise=current.exerciseIndex;const count=draft.items.flatMap(e=>e.sets).filter(s=>s.done).length,total=draft.items.reduce((n,e)=>n+e.sets.length,0);const header=dialogHeader(draft.paused?'训练已暂停':'正在训练')+`<div class="workout-player ${draft.paused?'is-paused':''}"><div class="player-meta"><span>${draft.mode==='free'?'自由训练':'跟计划练'}</span><button class="text-button" data-action="workout-options" aria-label="更多训练操作">更多 ···</button></div><div class="player-art" aria-hidden="true">${icon('dumbbell',48)}</div><div class="player-timeline"><div class="player-track"><i style="width:${total?Math.round(count/total*100):0}%"></i></div><div class="player-progress"><span>已完成 ${count}/${total} 组</span><strong id="workout-time">${elapsedText()}</strong></div></div>`;let body;if(draft.paused){body='<section class="paused-step"><h3>歇一会，随时继续</h3><p class="subtitle">'+escapeHTML(current?.exercise.name||draft.name||'本次训练')+'</p><p class="small-label">休息倒计时已暂停 · 总时长包含暂停时间</p></section>'}else if(!current){if(!draft.manualEnd){finishReview();return}body='<section class="single-set"><h3>本次训练进行中</h3><p class="subtitle">'+(count?'已完成 '+count+' 组，可以添加下一个动作。':'先添加一个动作或一项运动。')+'</p>'+sportDetails(draft.activities)+'</section>'}else if(restEnd>Date.now()){body=`<section class="single-set rest-step"><span class="step-kicker">这一组已记录</span><h3>休息一下，再继续</h3><div class="rest-clock-row"><strong class="rest-countdown" id="rest-time" role="timer">${timerText()}</strong><button class="rest-add-button" data-action="extend-rest" aria-label="延长休息30秒">+30s</button></div><p class="subtitle">下一组：${escapeHTML(current.exercise.name)} · ${current.setIndex+1}/${current.exercise.sets.length}</p><button class="primary-button" data-action="skip-rest">跳过休息，开始下一组</button><p class="small-label">倒计时结束后自动进入下一组</p></section>`}else{const e=current.exercise,index=current.setIndex,set=current.set;body=`<section class="single-set"><div class="single-set-heading"><span class="step-kicker">动作 ${selectedExercise+1}/${draft.items.length}</span><span class="set-progress">${index+1}/${e.sets.length} 组</span></div><div class="current-exercise-heading"><h3>${escapeHTML(e.name)}</h3></div><p class="subtitle">${escapeHTML(e.muscle)}</p><form id="current-set-form" data-current-set="${index}"><div class="current-set-fields">${(e.type||exerciseInfo(e).type)==='bodyweight'?'<div class="bodyweight-note">次数训练<br><small>无需记录 kg</small></div>':`<div class="field"><label for="current-weight">重量 / kg</label><input id="current-weight" type="number" min="0.5" max="1000" step="0.5" required data-set="${index}" data-field="weight" value="${set.weight>0?set.weight:recommendedWeight(e).weight}"><details class="weight-reference"><summary>重量参考说明</summary><p class="small-label">${recommendedWeight(e).source}</p></details></div>`}<div class="field"><label for="current-reps">次数</label><input id="current-reps" type="number" min="1" max="100" step="1" required data-set="${index}" data-field="reps" value="${set.reps}"></div></div><button class="primary-button" type="submit">完成本组</button></form></section>`};const controls=`<div class="player-controls"><button class="player-toggle" data-action="pause-workout" aria-label="${draft.paused?'继续训练':'暂停训练'}"><span aria-hidden="true">${draft.paused?'▶':'Ⅱ'}</span><small>${draft.paused?'继续':'暂停'}</small></button></div>${draft.paused?'<button class="hold-end player-end" data-hold-end="true" aria-label="长按1.2秒结束训练">长按结束训练<span>按住 1.2 秒，松开取消</span></button>':''}`;const add=!current&&!draft.paused?'<button class="secondary-button player-add" data-action="workout-add">＋ 添加训练项目</button>':'';openDialog(header+body+add+controls+'</div>');}
function lastCompletedSet(){let found=null;draft?.items.forEach((e,i)=>e.sets.forEach((s,j)=>{if(s.done&&(!found||(s.completedAt||0)>=(found.set.completedAt||0)))found={exerciseIndex:i,setIndex:j,exercise:e,set:s}}));return found}
function openWorkoutTool(content){openDialog(content);document.querySelector?.('#workout-content .dialog-content')?.classList?.add('workout-tool-screen');(document.querySelector?.('.workout-tool-menu button')||document.querySelector?.('.dialog-header button[data-action]'))?.focus?.()}
function openTrainingForm(content){if(draft)openWorkoutTool(content);else openDialog(content)}
function workoutToolRow(action,label,detail,ic='grid'){return '<button class="workout-tool-row" data-action="'+action+'"><span class="tool-icon">'+icon(ic,20)+'</span><span class="tool-copy"><strong>'+escapeHTML(label)+'</strong><small>'+escapeHTML(detail)+'</small></span><span class="tool-arrow" aria-hidden="true">›</span></button>'}
function workoutOptions(){if(!draft)return;const current=pendingSet(),last=lastCompletedSet();openWorkoutTool(dialogHeader('训练工具','back-workout',draft.finishedAt?'返回反馈':'返回训练')+'<section class="workout-tool-menu">'+(!draft.finishedAt?workoutToolRow('workout-add','添加训练项目','力量、次数训练或其他运动','play'):'')+(!draft.finishedAt&&current?workoutToolRow('tool-swap','替换当前动作',current.exercise.name+' · 已完成组保留','dumbbell'):'')+(last?workoutToolRow('tool-edit-last','修改上一组',last.exercise.name+' · 第 '+(last.setIndex+1)+' 组','check'):'')+workoutToolRow('workout-settings','训练设置','组间休息与草稿管理','clock')+'</section><p class="tool-state">'+(draft.finishedAt?'训练已结束，记录尚未保存':draft.paused?'当前已暂停，返回后可继续训练':'训练仍在计时，需要休息可返回后暂停')+'</p>')}
function workoutAddDialog(){if(!draft||draft.finishedAt)return;openWorkoutTool(dialogHeader('添加训练项目','workout-options','返回工具')+'<section class="workout-tool-menu">'+workoutToolRow('tool-strength','力量 / 次数训练','选择动作，填写组数、重量与次数','dumbbell')+workoutToolRow('tool-sport','其他运动','跑步、游泳、步行等，记录实际运动时长','fire')+'</section><p class="tool-state">添加后回到训练，所有项目统一结束保存。</p>')}
function workoutSettings(){if(!draft)return;openWorkoutTool(dialogHeader('训练设置','workout-options','返回工具')+'<section class="workout-settings-panel">'+restSelector()+'<p id="workout-rest-status" class="small-label" aria-live="polite"></p></section><div class="tool-danger-zone"><button class="text-button danger-button" data-action="tool-discard">放弃本次训练…</button><p class="small-label">需再次确认，已有历史记录不受影响。</p></div>')}
let lastSetBackAction='back-workout';
function editLastSet(back='back-workout'){const last=lastCompletedSet();if(!last)return;lastSetBackAction=back;const body=(last.exercise.type||exerciseInfo(last.exercise).type)==='bodyweight';openWorkoutTool(dialogHeader('修改上一组',back)+'<p class="subtitle">'+escapeHTML(last.exercise.name)+' · 第 '+(last.setIndex+1)+' 组</p><form id="last-set-form" class="profile-form">'+(body?'':'<div class="field"><label for="last-weight">重量 / kg</label><input id="last-weight" name="weight" type="number" min="0.5" max="1000" step="0.5" required value="'+last.set.weight+'"></div>')+'<div class="field"><label for="last-reps">次数</label><input id="last-reps" name="reps" type="number" min="1" max="100" step="1" required value="'+last.set.reps+'"></div><div class="full settings-actions"><button class="primary-button" type="submit">保存并返回'+(draft.finishedAt?'反馈':'训练')+'</button></div></form><div class="tool-danger-zone"><button class="text-button danger-button" data-action="undo-last-prompt">撤销这一组完成…</button></div>')}
function undoLastPrompt(){const last=lastCompletedSet();if(!last)return;openWorkoutTool(dialogHeader('撤销这一组完成？','back-edit-last')+'<p class="subtitle">'+escapeHTML(last.exercise.name)+' · 第 '+(last.setIndex+1)+' 组将恢复为未完成，当前休息会结束。</p><div class="settings-actions"><button class="primary-button" data-action="back-edit-last">保留这一组</button><button class="text-button danger-button" data-action="undo-last-set">确认撤销，重新记录</button></div>')}
function updateLastSet(values,undo=false){const last=lastCompletedSet();if(!last)return false;const body=(last.exercise.type||exerciseInfo(last.exercise).type)==='bodyweight',reps=Number(values?.reps),weight=body?null:Number(values?.weight);if(!undo&&(!Number.isInteger(reps)||reps<1||reps>100||(!body&&(!Number.isFinite(weight)||weight<0.5||weight>1000)))){toast('请填写有效的重量和整数次数');return false}const next=JSON.parse(JSON.stringify(draft)),set=next.items[last.exerciseIndex].sets[last.setIndex];if(undo){set.done=false;delete set.completedAt;delete next.finishedAt;next.restEnd=0;delete next.pausedRest;next.activeExercise=last.exerciseIndex}else Object.assign(set,{weight,reps});if(!saveLocal('nextstep.draft',next))return false;draft=next;restEnd=next.restEnd||0;selectedExercise=next.activeExercise||0;workoutDialog();return true}
function discardPrompt(back='back-workout'){openWorkoutTool(dialogHeader('放弃本次训练？',back)+'<p class="subtitle">本次未保存的组和计时将被删除，已有历史记录不受影响。</p><div class="settings-actions"><button class="primary-button" data-action="'+back+'">保留本次训练</button><button class="text-button danger-button" data-action="discard-workout">确认放弃</button></div>')}
function discardWorkout(){try{localStorage.removeItem('nextstep.draft')}catch{toast('草稿删除失败，请重试');return false}cancelEndHold();draft=null;restEnd=0;selectedExercise=0;document.getElementById('workout-dialog').close();render();toast('已放弃本次训练');return true}
function changeWorkoutRest(value){const seconds=Number(value);if(![60,90,120,180].includes(seconds))return false;if(draft){const next={...draft,restSeconds:seconds};if(!saveLocal('nextstep.draft',next))return false;draft=next}else{const next={...profile,restSeconds:seconds};if(!saveLocal('nextstep.profile',next))return false;profile=next}return true}
function timerText(){const seconds=Math.max(0,Math.ceil((restEnd-Date.now())/1000));return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`}
setInterval(()=>{const el=document.getElementById('rest-time');if(el){el.textContent=timerText();if(draft&&restEnd<=Date.now()&&document.getElementById('workout-dialog').open)endRest()}const elapsed=document.getElementById('workout-time');if(elapsed)elapsed.textContent=elapsedText()},1000);
function finishWorkout(){if(!draft)return;const completed=draft.items.flatMap(e=>e.sets).filter(s=>s.done);if(draft.items.some(e=>(e.type||exerciseInfo(e).type)!=='bodyweight'&&e.sets.some(s=>s.done&&!(s.weight>0)))){toast('负重训练不能保存0 kg的组，请确认实际重量');return}if(!completed.length&&!draft.activities?.length){toast('先完成一组或添加一项运动');return}const record={id:Date.now(),workoutId:String(draft.startedAt),name:draft.name||'力量训练',mode:draft.mode||'plan',feeling:draft.feedback||'未反馈',startedAt:draft.startedAt,endedAt:draft.finishedAt||Date.now(),seconds:Math.max(0,Math.floor(((draft.finishedAt||Date.now())-draft.startedAt)/1000)),date:localDate(new Date(draft.startedAt)),minutes:Math.max(1,Math.round(((draft.finishedAt||Date.now())-draft.startedAt)/60000)),activities:JSON.parse(JSON.stringify(draft.activities||[])),exercises:draft.items.filter(e=>e.sets.some(s=>s.done)).length+(draft.activities?.length||0),sets:completed.length,volume:draft.items.reduce((sum,e)=>sum+((e.type||exerciseInfo(e).type)==='bodyweight'?0:e.sets.filter(s=>s.done).reduce((n,s)=>n+s.weight*s.reps,0)),0),items:JSON.parse(JSON.stringify(draft.items)).map(e=>({...e,type:e.type||exerciseInfo(e).type,sets:e.sets.map(s=>({...s,weight:(e.type||exerciseInfo(e).type)==='bodyweight'?null:s.weight}))}))};const existing=records.find(r=>r.workoutId===record.workoutId||r.startedAt===record.startedAt);if(existing){toast('本次训练已经保存');return}const nextRecords=[record,...records];if(!saveLocal('nextstep.records',nextRecords))return;records=nextRecords;draft=null;restEnd=0;try{localStorage.removeItem('nextstep.draft')}catch{}openDialog(dialogHeader('训练完成，做得很好。')+`<p class="subtitle">这次训练已保存到当前浏览器。</p><div class="stats-grid" style="grid-template-columns:1fr 1fr;margin-top:24px"><div class="stat"><div class="stat-head">完成组数</div><div class="stat-number">${record.sets}<small>组</small></div></div><div class="stat"><div class="stat-head">训练时长</div><div class="stat-number">${record.minutes}<small>分钟</small></div></div></div><div class="soft-note">消耗、恢复与下次建议尚未接入计算。本次逐组表现已保留，后续可以用于分析。</div><div class="card-actions"><button class="primary-button" data-action="view-records">查看训练记录</button></div>`);render()}
function swapDialog(back='back-workout'){const current=draft?.items[selectedExercise];if(!current)return;openWorkoutTool(dialogHeader('替换当前动作',back)+'<p class="subtitle">已完成的组保留，替换只影响尚未完成的组。</p>'+projectPicker('swap'))}
function replaceExercise(name){const info=exerciseCatalog.find(e=>e.name===name);if(!info||!draft)return;const old=draft.items[selectedExercise],completed=old.sets.filter(s=>s.done),count=old.sets.filter(s=>!s.done).length;if(!count)return;const next=JSON.parse(JSON.stringify(draft));if(completed.length){next.items[selectedExercise].sets=completed;next.items.splice(selectedExercise+1,0,makeWorkoutItem({...info,sets:count,reps:old.sets[0].reps}));selectedExercise++}else next.items[selectedExercise]=makeWorkoutItem({...info,sets:count,reps:old.sets[0].reps});next.activeExercise=selectedExercise;if(!saveLocal('nextstep.draft',next))return;draft=next;workoutDialog()}
let holdTimer=null,holdButton=null,holdPointerId=null,suppressEndClick=false;
function cancelEndHold(){clearTimeout(holdTimer);holdTimer=null;holdButton=null;holdPointerId=null;document.querySelectorAll?.('.hold-end.is-holding').forEach(b=>b.classList.remove('is-holding'))}
function beginEndHold(button,pointerId=null){if(!draft||!draft.paused||!button)return;cancelEndHold();holdButton=button;holdPointerId=pointerId;button.classList.add('is-holding');holdTimer=setTimeout(()=>{holdTimer=null;if(draft?.paused&&button.isConnected&&document.getElementById('workout-dialog').open){if(pointerId!==null)suppressEndClick=true;finishReview()}},1200)}
function moveEndHold(event){if(!holdButton||event.pointerId!==holdPointerId)return;const r=holdButton.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)cancelEndHold()}
function suppressEndHoldClick(event){if(!suppressEndClick)return;suppressEndClick=false;event.preventDefault();event.stopImmediatePropagation()}
document.addEventListener('pointerdown',event=>{if(event.isPrimary===false)return;suppressEndClick=false;const b=event.target.closest('[data-hold-end]');if(b&&event.button===0)beginEndHold(b,event.pointerId)});
document.addEventListener('pointermove',moveEndHold,true);
for(const type of ['pointerup','pointercancel'])document.addEventListener(type,event=>{if(holdPointerId===null||event.pointerId===holdPointerId)cancelEndHold()},true);
document.addEventListener('pointerleave',event=>{if(event.target===holdButton&&event.pointerId===holdPointerId)cancelEndHold()},true);
document.addEventListener('keydown',event=>{const b=event.target.closest('[data-hold-end]');if(b&&[' ','Enter'].includes(event.key)){event.preventDefault();if(!event.repeat)beginEndHold(b)}});
document.addEventListener('visibilitychange',cancelEndHold);document.addEventListener('keyup',cancelEndHold);window.addEventListener('blur',cancelEndHold);
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.projectKey){chooseProject(button.dataset.projectMode,button.dataset.projectKey);return}if(button.dataset.workoutFeel&&draft){const next={...draft,feedback:button.dataset.workoutFeel};if(saveLocal('nextstep.draft',next)){draft=next;finishReview()}return}if(button.dataset.calendarDate){selectCalendarDay(button.dataset.calendarDate);return}if(button.dataset.editRecord){recordEditDialog(button.dataset.editRecord);return}if(button.dataset.deleteRecord){recordDeleteDialog(button.dataset.deleteRecord);return}if(button.dataset.confirmDelete){deleteRecord(button.dataset.confirmDelete);return}if(button.dataset.record){recordDialog(button.dataset.record);return}if(button.dataset.page){navigate(button.dataset.page);return}if(button.dataset.period){changePeriod(button.dataset.period);return}if(button.dataset.day!==undefined){changePlanDay(Number(button.dataset.day));return}if(button.dataset.exercise!==undefined){selectedExercise=Number(button.dataset.exercise);if(draft){draft.activeExercise=selectedExercise;saveLocal('nextstep.draft',draft)}workoutDialog();return}if(button.dataset.complete!==undefined&&draft){completeSet(Number(button.dataset.complete));return}if(button.dataset.swap){replaceExercise(button.dataset.swap);return}switch(button.dataset.action){case 'app-updates':if(window.NextStepAndroid&&typeof window.NextStepAndroid.openAppUpdates==='function')window.NextStepAndroid.openAppUpdates();break;case 'health-save':retryStepSave();break;case 'health-read':refreshHealthSteps(true);break;case 'health-settings':if(healthNative())window.NextStepAndroid.openHealthSettings();break;case 'health-privacy':if(healthNative())window.NextStepAndroid.showHealthPrivacy();break;case 'pause-workout':toggleWorkoutPause();break;case 'workout-options':workoutOptions();break;case 'workout-add':workoutAddDialog();break;case 'tool-strength':freeSetup('workout-add');break;case 'tool-sport':sportSetup('workout-add');break;case 'tool-swap':swapDialog('workout-options');break;case 'tool-edit-last':editLastSet('workout-options');break;case 'workout-settings':workoutSettings();break;case 'tool-discard':discardPrompt('workout-settings');break;case 'undo-last-prompt':undoLastPrompt();break;case 'back-edit-last':editLastSet(lastSetBackAction);break;case 'back-workout':workoutDialog();break;case 'edit-last-set':editLastSet();break;case 'undo-last-set':updateLastSet(null,true);break;case 'discard-prompt':discardPrompt();break;case 'discard-workout':discardWorkout();break;case 'settings':openSettings();break;case 'dismiss-reminder':reminderDismissed=true;document.getElementById('workout-dialog').close();render();break;case 'start':workoutModeDialog();break;case 'start-session':startSession();break;case 'start-plan':startWorkout();break;case 'free-setup':freeSetup();break;case 'back-mode':workoutModeDialog();break;case 'sport-setup':sportSetup();break;case 'close':document.getElementById('workout-dialog').close();render();break;case 'skip-rest':endRest();break;case 'finish':finishReview();break;case 'save-workout':finishWorkout();break;case 'resume-workout':{const next={...draft,paused:false};delete next.finishedAt;if(next.pausedRest>0)next.restEnd=Date.now()+next.pausedRest;delete next.pausedRest;if(saveLocal('nextstep.draft',next)){draft=next;restEnd=next.restEnd||0;workoutDialog()}break;}case 'extend-rest':extendRest();break;case 'view-records':document.getElementById('workout-dialog').close();navigate('training');break;case 'swap':swapDialog();break;case 'export':{const url=URL.createObjectURL(new Blob([JSON.stringify(exportData(),null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='nextstep-training.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出本地资料、训练和活动记录');break}}});
// Capture the release click before it can act on the newly rendered feedback dialog.
document.addEventListener('click',suppressEndHoldClick,true);
function persistSetInput(event){const el=event.target;if(el.dataset.projectSearch||el.dataset.projectGroup){if(el.dataset.projectSearch&&event.type==='change')return;updateProjectPicker(el.dataset.projectSearch||el.dataset.projectGroup);return}if(el.id==='workout-rest'){if(changeWorkoutRest(el.value)){const status=document.getElementById('workout-rest-status');if(status)status.textContent='已保存，下次休息 '+Number(el.value)+' 秒'}else{el.value=String(draft?.restSeconds||defaultRestSeconds());const status=document.getElementById('workout-rest-status');if(status)status.textContent='保存失败，请重新选择后重试'}return}if(['free-catalog','free-type'].includes(el.id)){updateFreeForm(el);return}if(['sport-type','sport-minutes','sport-weight'].includes(el.id)){const calories=estimatedCalories(document.getElementById('sport-type').value,Number(document.getElementById('sport-minutes').value),Number(document.getElementById('sport-weight').value));document.getElementById('sport-estimate').textContent=calories===null?'填写时长和体重后显示预估热量':'预计约 '+calories+' kcal（估算）';return}if(el.id==='rest-seconds'&&draft){draft.restSeconds=Number(el.value);saveLocal('nextstep.draft',draft);return}if(el.dataset.set===undefined||!draft||draft.paused)return;const field=el.dataset.field;const value=field==='feel'?el.value:Number(el.value);const invalid=field!=='feel'&&(el.value===''||!Number.isFinite(value)||value<Number(el.min)||value>Number(el.max)||(field==='reps'&&!Number.isInteger(value)));if(invalid){el.setAttribute?.('aria-invalid','true');if(event.type==='change')toast('请修正当前输入后再完成本组');return}el.removeAttribute?.('aria-invalid');draft.items[selectedExercise].sets[Number(el.dataset.set)][field]=value;saveLocal('nextstep.draft',draft)}
document.addEventListener('input',persistSetInput);
document.addEventListener('change',persistSetInput);
document.addEventListener('submit',event=>{if(event.target.id==='last-set-form'){event.preventDefault();if(event.target.reportValidity())updateLastSet(Object.fromEntries(new FormData(event.target)));return}if(event.target.id==='record-edit-form'){event.preventDefault();if(event.target.reportValidity())updateRecord(event.target.dataset.id,Object.fromEntries(new FormData(event.target)));return}if(event.target.id==='current-set-form'){event.preventDefault();if(event.target.reportValidity()){const weight=document.getElementById('current-weight');if(weight&&event.target.contains(weight))persistSetInput({target:weight,type:'input'});completeSet(Number(event.target.dataset.currentSet));}return}if(event.target.id==='sport-form'){event.preventDefault();if(event.target.reportValidity())saveSport(Object.fromEntries(new FormData(event.target)));return}if(event.target.id==='free-form'){event.preventDefault();if(event.target.reportValidity())startFreeWorkout(Object.fromEntries(new FormData(event.target)));return}if(event.target.id!=='profile-form')return;event.preventDefault();if(!event.target.reportValidity())return;const values=Object.fromEntries(new FormData(event.target));if(saveProfile(values)){document.getElementById('workout-dialog').close();navigate('plan');toast('资料已更新，训练计划已生成')}});
document.getElementById('workout-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close()}});
window.addEventListener('hashchange',()=>{if(location.hash==='#profile'){render('plan');openSettings();return}if(location.hash==='#today-details'&&currentPage==='today')return;render(location.hash==='#trends'?'training':pages.some(p=>p[0]===location.hash.slice(1))?location.hash.slice(1):'today')});
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'navigate_training_page',description:'Navigate to an existing NextStep view without changing training records.',inputSchema:{type:'object',properties:{page:{type:'string',enum:pages.map(p=>p[0])}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||!pages.some(p=>p[0]===input.page))throw new Error('Unknown page');navigate(input.page);return {page:currentPage}}})}catch{}}
render(location.hash==='#trends'?'training':location.hash==='#profile'?'plan':pages.some(p=>p[0]===location.hash.slice(1))?location.hash.slice(1):'today');
if((reminderReason&&!draft)||location.hash==='#profile')openSettings();
saveLocal('nextstep.lastActive',Date.now());
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){const previous=Number(readLocal('nextstep.lastActive',0));if(previous&&Date.now()-previous>=30*86400000){reminderReason='return';reminderDismissed=false;render();if(!document.getElementById('workout-dialog').open&&!draft)openSettings()}saveLocal('nextstep.lastActive',Date.now())}});
setInterval(()=>{if(document.visibilityState==='visible')saveLocal('nextstep.lastActive',Date.now())},60000);

document.addEventListener('contextmenu',event=>{if(event.target.closest('[data-hold-end]'))event.preventDefault()});
